@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    # If the object is not actually an exception, just return its string representation.
    if not isinstance(e, BaseException):
        return str(e)

    # Basic information: type name and message.
    exc_type = e.__class__.__name__
    exc_msg = str(e)

    # Collect traceback frames, limiting the number of levels.
    tb = getattr(e, "__traceback__", None)
    frames = []
    if tb is not None:
        try:
            frames = traceback.extract_tb(tb, limit=max_level)
        except Exception:
            # Fallback if extract_tb fails (unlikely but safe)
            try:
                frames = traceback.extract_tb(sys.exc_info()[2], limit=max_level)
            except Exception:
                frames = []

    # Format each frame, shortening file paths when necessary.
    formatted_frames = []
    for f in frames:
        file_path = f.filename
        parts = file_path.split(os.sep)
        if len(parts) > max_path_level:
            file_path = os.sep.join(parts[-max_path_level:])
        line_content = f.line or ""
        formatted_frames.append(
            f'\tFile "{file_path}", line {f.lineno}, in {f.name}\n\t    {line_content}'
        )

    tb_str = "\n".join(formatted_frames)

    # Construct the final output.
    if tb_str:
        return (
            f"{exc_type}: {exc_msg}\n"
            f"Traceback (most recent call last):\n"
            f"{tb_str}"
        )
    else:
        return f"{exc_type}: {exc_msg}"

