def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Convert to list if an iterable
    if not isinstance(classes, (list, tuple)):
        classes = list(classes)

    # Find classes that are not superclasses of any other class in the list
    minimal_set = set()
    for c in classes:
        if not isinstance(c, type):
            continue
        # Check if any other class is a subclass of c
        is_super = False
        for other in classes:
            if other is c:
                continue
            try:
                if issubclass(other, c):
                    is_super = True
                    break
            except TypeError:
                continue
        if not is_super:
            minimal_set.add(c)

    # Preserve the original order
    return [c for c in classes if c in minimal_set]

