    use :class:`lena.output.ToCSV`.
    """
    def _flatten(item):
        if isinstance(item, (str, bytes)):
            return [item]
        try:
            iter(item)
        except TypeError:
            return [item]
        else:
            return list(item)

    lines = []
    if header is not None:
        lines.append(header)

    for coord, value in self:
        parts = []
        parts.extend(_flatten(coord))
        parts.extend(_flatten(value))
        line = separator.join(str(p) for p in parts)
        lines.append(line)

    return "\n".join(lines)

