def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("fixity must be a dictionary")
    required_keys = {"algorithm", "hashes"}
    missing = required_keys - set(fixity.keys())
    if missing:
        raise ValueError(f"Missing required keys in fixity block: {missing}")
    algo = fixity.get("algorithm")
    if not isinstance(algo, str) or not algo:
        raise ValueError("fixity['algorithm'] must be a non-empty string")
    hashes = fixity.get("hashes")
    if not isinstance(hashes, dict):
        raise ValueError("fixity['hashes'] must be a dictionary")
    for fname, hval in hashes.items():
        if fname not in manifest_files:
            raise ValueError(f"File '{fname}' referenced in fixity but not present in the manifest")
        if not isinstance(hval, str) or not hval:
            raise ValueError(f"Hash for '{fname}' must be a non-empty string")
    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure the fixity data is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")

    # All files mentioned in the fixity block must exist in the manifest
    for file_name in fixity:
        if file_name not in manifest_files:
            raise ValueError("Fixity refers to unknown file: %s" % file_name)

    # Validate each file's fixity entry for correct structure
    for file_name, entry in fixity.items():
        if not isinstance(entry, dict):
            raise ValueError("Fixity entry for %s must be a dictionary." % file_name)

        if not entry:
            raise ValueError("Empty fixity entry for %s." % file_name)

        # A typical fixity entry should contain a checksum
        if 'checksum' not in entry or not entry['checksum']:
            raise ValueError("Missing or empty checksum for %s." % file_name)

    # If we reach here, the fixity block is considered valid
    return True

