def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, Node) tuples for borgmatic YAML configs.
    Duplicate keys are merged recursively. When the value for a duplicate key
    is a plain scalar or any non‑MappingNode, the later one wins.
    """
    def _merge_mapping_nodes(a, b):
        # a and b are MappingNode instances
        merged = {}
        for key_a, val_a in a.value:
            merged[key_a.value] = (key_a, val_a)
        for key_b, val_b in b.value:
            if key_b.value in merged:
                key_a, val_a = merged[key_b.value]
                merged[key_b.value] = (key_a, _merge_values(val_a, val_b))
            else:
                merged[key_b.value] = (key_b, val_b)
        return ruamel.yaml.nodes.MappingNode(a.tag, list(merged.values()))

    def _merge_values(a, b):
        if isinstance(a, ruamel.yaml.nodes.MappingNode) and isinstance(b, ruamel.yaml.nodes.MappingNode):
            return _merge_mapping_nodes(a, b)
        # In all other cases, the later value wins
        return b

    merged = {}
    for key, val in nodes:
        key_id = key.value
        if key_id in merged:
            prev_key, prev_val = merged[key_id]
            merged[key_id] = (prev_key, _merge_values(prev_val, val))
        else:
            merged[key_id] = (key, val)

    return [(k, v) for k, v in merged.values()]

