        if getattr(node_a, 'tag', None) == 'tag:yaml.org,2002:map' and getattr(node_b, 'tag', None) == 'tag:yaml.org,2002:map':
            return _merge_mapping_nodes(node_a, node_b)
        return node_b  # last wins for non-mapping nodes

