def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    parsed_configs = {}
    error_records = []

    # Import modules lazily
    try:
        import yaml
    except ImportError:
        yaml = None
    try:
        import toml
    except ImportError:
        toml = None

    for filename in config_filenames:
        try:
            if not os.path.isfile(filename):
                raise FileNotFoundError(f"Configuration file not found: {filename}")

            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
            # Determine parser by file extension
            if filename.lower().endswith('.toml'):
                if toml is None:
                    raise ImportError("toml module not available")
                config = toml.loads(content) if content else {}
            elif filename.lower().endswith(('.yaml', '.yml')):
                if yaml is None:
                    raise ImportError("yaml module not available")
                config = yaml.safe_load(content) if content else {}
            else:
                # Unsupported format: treat as plain text
                raise ValueError(f"Unsupported configuration file format: {filename}")

            # Apply overrides if provided
            if overrides:
                config.update(overrides)

            # Resolve environment variables if required
            if resolve_env:
                for key, value in config.items():
                    if isinstance(value, str):
                        config[key] = os.path.expandvars(value)

            parsed_configs[filename] = config

        except Exception as exc:
            # Create a LogRecord to hold the error
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(exc),
                args=None,
                exc_info=None
            )
            error_records.append(record)

    return parsed_configs, error_records

