    return self

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # First, handle the getter case
    if other is None:
        return getattr(self, "scale", None)

    # Setter case: compute the scaling factor
    try:
        target_scale = float(other)
    except Exception as exc:
        raise TypeError("Scale must be a numeric value") from exc

    current_scale = getattr(self, "scale", None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError(
            "Cannot rescale when graph's scale is unknown or zero"
        )

    ratio = target_scale / current_scale

    # Rescale only the last coordinate (and its errors)
    # Assume the coordinates are stored in a NumPy array
    if hasattr(self, "data") and isinstance(self.data, np.ndarray):
        self.data[:, -1] *= ratio
    else:
        # Fallback: try a more generic attribute
        if hasattr(self, "values"):
            vals = getattr(self, "values")
            if isinstance(vals, np.ndarray):
                vals[:, -1] *= ratio

    # Rescale the corresponding errors, if any
    if hasattr(self, "errors") and isinstance(self.errors, dict):
        # Find the name of the last field
        last_field = None
        if hasattr(self, "fields") and isinstance(self.fields, (list, tuple)):
            if self.fields:
                last_field = self.fields[-1]
        # If the last field name is known, use it
        if last_field and last_field in self.errors:
            err = self.errors[last_field]
            if hasattr(err, "__len__") and not isinstance(err, (str, bytes)):
                self.errors[last_field] = np.asarray(err) * ratio
        else:
            # If no named fields, fall back to scaling the last column of error array
            for name, err in self.errors.items():
                if isinstance(err, np.ndarray) and err.ndim > 0:
                    self.errors[name] = err * ratio

    # Update the scale attribute and return the new scale
    self.scale = target_scale
    return target_scale

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                   field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create graph with errors from a histogram where bins
    contain a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate of a graph point created
    from a histogram bin will be. It can be "left" (default), "right" and
    "middle".

    *field_names* set field names of the graph. Their number must be
    the same as the dimension of the result.
    For a *make_value* above they would be *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context) or
    *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.

    """
    # Default value maker if none provided
    if make_value is None:
        make_value = lambda v: v

    # Attempt to get bin edges and bin contents from the histogram
    try:
        edges = hist.edges
    except AttributeError:
        try:
            edges = hist.edges_
        except AttributeError:
            raise AttributeError("Histogram object missing 'edges' attribute")

    try:
        bins = hist.values
    except AttributeError:
        try:
            bins = hist.bins
        except AttributeError:
            # fall back to using the histogram as an array of values
            bins = hist

    if len(edges) - 1 != len(bins):
        raise ValueError("Number of bin values must equal number of bin edges minus one")

    # Determine coordinate values per bin
    if get_coordinate == "left":
        coords = edges[:-1]
    elif get_coordinate == "right":
        coords = edges[1:]
    elif get_coordinate == "middle":
        coords = [(l + r) / 2.0 for l, r in zip(edges[:-1], edges[1:])]
    else:
        raise ValueError(f"Unrecognized get_coordinate value: {get_coordinate!r}")

    # Build points for the graph
    points = []
    for x, val in zip(coords, bins):
        result = make_value(val)
        # Ensure result is a tuple or list for consistency
        if not isinstance(result, (tuple, list)):
            result = (result,)
        # Validate field count
        if len(result) + 1 != len(field_names):
            raise ValueError(
                "Result of make_value must produce %(n)d values (got %(m)d) to match field_names"
                % {"n": len(field_names) - 1, "m": len(result)}
            )
        points.append((x,) + tuple(result))

    # Create the graph object; we assume a Graph class is available in this scope
    try:
        graph = Graph(points, field_names=field_names)
    except NameError as exc:
        raise NameError("Graph class is not available in the current scope") from exc

    # Handle the scale argument
    if scale is True:
        # attempt to copy histogram's scale
        try:
            graph.scale = hist.scale
        except AttributeError:
            # no scale defined on histogram; leave graph.scale as is
            pass
    elif scale is not None:
        graph.scale = scale

    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.
    """
    errors = []

    # 1. Check interface implementation claim
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                raise zope.interface.Invalid(
                    f"{candidate} does not claim to provide interface {iface}"
                )
        except Exception as exc:
            # providedBy may raise if candidate is not an object
            raise zope.interface.Invalid(
                f"Failed to check providedBy for {candidate} and {iface}: {exc}"
            ) from exc

    # Helper to compare signatures (ignoring 'self')
    def signatures_match(fun_iface, fun_cand):
        import inspect
        sig_iface = inspect.signature(fun_iface)
        sig_cand = inspect.signature(fun_cand)
        params_iface = list(sig_iface.parameters.values())
        params_cand = list(sig_cand.parameters.values())

        # Remove implicit 'self' for instance methods
        if params_iface and params_iface[0].name == 'self':
            params_iface = params_iface[1:]
        if params_cand and params_cand[0].name == 'self':
            params_cand = params_cand[1:]

        # Compare parameter counts
        if len(params_iface) != len(params_cand):
            return False
        # Compare parameter names
        for piface, pcand in zip(params_iface, params_cand):
            if piface.name != pcand.name:
                return False
            # Optionally compare kinds (positional-only, keyword-only, etc.)
            if piface.kind != pcand.kind:
                return False
        return True

    # 2. Inspect interface names
    try:
        # ``names`` is an iterator over defined attribute names in the interface
        names = list(iface.names())
    except Exception as exc:
        raise zope.interface.Invalid(
            f"Cannot retrieve names from interface {iface}: {exc}"
        ) from exc

    for name in names:
        # Skip internal names like __module__, etc.
        if name.startswith('_'):
            continue

        # Check candidate has the attribute/method
        if not hasattr(candidate, name):
            errors.append(f"Candidate missing attribute or method '{name}'")
            continue

        cand_attr = getattr(candidate, name)
        try:
            iface_attr = getattr(iface, name)
        except Exception:
            # Attribute not defined in interface (should not happen)
            continue

        # Distinguish between method and attribute
        if callable(iface_attr):
            # It's a method in the interface
            if not callable(cand_attr):
                errors.append(f"Attribute '{name}' is not callable on candidate")
            else:
                try:
                    if not signatures_match(iface_attr, cand_attr):
                        errors.append(
                            f"Signature mismatch for method '{name}'"
                        )
                except Exception as exc:
                    errors.append(
                        f"Could not compare signatures for method '{name}': {exc}"
                    )
        else:
            # It's expected to be a data attribute
            if not hasattr(candidate, name):
                errors.append(f"Attribute '{name}' missing on candidate")

    # 3. Raise aggregated errors
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("; ".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    This function checks that either `candidate` is a subclass of `iface`
    or it implements all public callable attributes defined on `iface`.
    If `tentative` is True, the function will return False instead of
    raising an exception when the candidate does not satisfy the
    interface.  Otherwise, a TypeError is raised listing the missing
    or incorrect members.
    """
    if not isinstance(iface, type):
        raise TypeError("iface must be a class or type")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a class or type")

    # Fast path: subclass relationship
    if issubclass(candidate, iface):
        return True

    # Check that candidate implements all public callable attributes of iface
    missing = []
    for name in dir(iface):
        if name.startswith('_'):  # skip private/magic attributes
            continue
        iface_attr = getattr(iface, name)
        if callable(iface_attr):
            if not hasattr(candidate, name):
                missing.append(name)
            else:
                candidate_attr = getattr(candidate, name)
                if not callable(candidate_attr):
                    missing.append(name)

    if missing:
        if tentative:
            return False
        raise TypeError(
            f"Candidate class {candidate.__name__} does not implement required methods: "
            f"{', '.join(missing)}"
        )
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__."""

    # If an explicit metaclass is supplied, use it directly.
    if explicit_mc is not None:
        return explicit_mc

    if not bases:
        # No bases means the default metaclass is `type`.
        return type

    # Compute the implicit metaclass based on the bases.
    metaclasses = [type(b) for b in bases]
    chosen = metaclasses[0]
    for m in metaclasses[1:]:
        if issubclass(m, chosen):
            chosen = m
        elif not issubclass(chosen, m):
            raise TypeError(
                f"cannot combine metaclasses {chosen!r} "
                f"and {m!r} for bases {bases!r}"
            )

    return chosen

