def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Base candidate for metaclass (default is 'type')
    candidate = type

    # Helper to resolve conflicts between two metaclasses
    def _resolve(metaA, metaB):
        if issubclass(metaA, metaB):
            return metaA
        if issubclass(metaB, metaA):
            return metaB
        raise TypeError(f"metaclass conflict: {metaA} conflicts with {metaB}")

    # Process metaclasses of the provided bases
    for base in bases:
        if base is None:
            continue
        if not isinstance(base, type):
            raise TypeError(f"base {base!r} is not a class")
        candidate = _resolve(type(base), candidate)

    # Incorporate the explicit metaclass if given
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit metaclass {explicit_mc!r} is not a metaclass")
        candidate = _resolve(explicit_mc, candidate)

    return candidate

