        root = ET.fromstring(doc)
    except Exception:
        return False
    # Locate the XML Signature element
    sig_elem = root.find('.//{http://www.w3.org/2000/09/xmldsig#}Signature')
    if sig_elem is None:
        return False
    # Create a signature context and load the public key
    try:
        ctx = xmlsec.SignatureContext()
        key = xmlsec.Key.from_file(public_key, xmlsec.KeyFormat.PEM)
        ctx.key = key
        # Validate the signature
        return ctx.verify(sig_elem)
    except Exception:
        return False

