    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Try to retrieve the command from the internal registry.  The exact
    # structure of the registry may vary – many CLI frameworks keep a
    # dictionary that maps command names to command objects, parser
    # instances, or other representations.
    try:
        cmd = self.commands[command_name]
    except KeyError:
        # Unknown command – simply return an empty list.
        return []

    # Common patterns for representing command options:

    # 1. If the command object exposes its own ArgumentParser through a
    #    `.parser` attribute, we can return the list of actions.
    if hasattr(cmd, "parser"):
        parser = cmd.parser
        if isinstance(parser, argparse.ArgumentParser):
            return list(parser._actions)

    # 2. Some frameworks expose a list or tuple directly in an
    #    `.options` attribute.
    if hasattr(cmd, "options"):
        return list(cmd.options)

    # 3. As a last resort, if the command object provides an
    #    `.get_option_spec()` method, we use it.
    if hasattr(cmd, "get_option_spec") and callable(cmd.get_option_spec):
        return list(cmd.get_option_spec())

    # If none of the above apply, return an empty list to signify no
    # custom options were found for the command.
    return []

