            if key not in spec_option:
                raise ValueError(f'Unknown field {key!r} for {option_name!r}')
            try:
                kwargs[key] = spec_option[key](val)
            except Exception as exc:
                raise ValueError(f'Error converting field {key!r} with value {val!r}: {exc!s}')
