    if hasattr(subcommand, 'add_argument'):
        subcommand.add_argument(
            option_name,
            type=_parse,
            help=(
                f'{type_name} argument represented as comma separated key=value pairs. '
                f'Expected fields: {", ".join(field_names)}'
